import {
  callMethod,
  defineController,
  readProperty,
  writeProperty,
  type ControllerContext,
  type FunctionalController
} from "./functional_controller_runtime"

export const planningLockSyncIdentifier = "planning-lock-sync"

const lockSelector = "input[name='lock_version']"

const lockValueFrom = (target: unknown): string => {
  const input = callMethod(target, "querySelector", [lockSelector])
  const value = readProperty(input, "value")
  return typeof value === "string" && /^\d+$/u.test(value) ? value : ""
}

const sync = (context: ControllerContext): unknown => {
  const value = lockValueFrom(readProperty(context.event, "target"))
  const inputs = callMethod(context.element, "querySelectorAll", [lockSelector])
  return value.length === 0 || inputs === undefined
    ? false
    : Object.freeze(Array.from(inputs as ArrayLike<unknown>).map((input) => writeProperty(input, "value", value)))
}

const PlanningLockSyncController: FunctionalController = defineController({
  actions: Object.freeze({ sync })
})

export default PlanningLockSyncController

