import {
  callMethod,
  defineController,
  findTarget,
  findTargets,
  preventDefault,
  readProperty,
  writeProperty,
  type ControllerContext,
  type FunctionalController
} from "./functional_controller_runtime"

const pendingKey = "__planningMutationPending"
const disabledKey = "__planningMutationDisabled"

export type PlanningMutationState = "error" | "saved" | "saving" | "unsaved"

export const planningMutationStateMessage = (state: PlanningMutationState, savedAt = ""): string =>
  state === "unsaved"
    ? "Unsaved changes"
    : state === "saving"
      ? "Saving…"
      : state === "saved"
        ? `Saved at ${savedAt}`
        : "Couldn't save. Review the highlighted fields and try again."

export const planningMutationMessage = (success: boolean): string =>
  success ? planningMutationStateMessage("saved", new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })) : planningMutationStateMessage("error")

const immutableElements = (value: unknown): Readonly<ReadonlySet<unknown>> =>
  Object.freeze(new Set(value === undefined ? [] : Array.from(value as ArrayLike<unknown>)))

const submissionControls = (context: ControllerContext): Readonly<ReadonlySet<unknown>> => {
  const targets: Readonly<ReadonlySet<unknown>> = immutableElements(findTargets(context.element, context.identifier, "submit"))
  const formControls: Readonly<ReadonlySet<unknown>> = immutableElements(callMethod(
    readProperty(context.event, "target"),
    "querySelectorAll",
    ['button[type="submit"], input[type="submit"], [data-planning-mutation-lock]']
  ))
  return Object.freeze(new Set([...targets, ...formControls]))
}

const announce = (context: ControllerContext, message: string): unknown =>
  writeProperty(findTarget(context.element, context.identifier, "status"), "textContent", message)

const markUnsaved = (context: ControllerContext): unknown =>
  readProperty(context.element, pendingKey) === true ? false : announce(context, planningMutationStateMessage("unsaved"))

const focusFirstError = (context: ControllerContext): unknown =>
  callMethod(callMethod(
    context.element,
    "querySelector",
    ['[aria-invalid="true"]:not([disabled]), [data-planning-mutation-field-error]']
  ), "focus", [])

const focusFailure = (context: ControllerContext): unknown =>
  callMethod(
    callMethod(
      context.element,
      "querySelector",
      ['[aria-invalid="true"]:not([disabled]), [data-planning-mutation-field-error]']
    ) ?? findTarget(context.element, context.identifier, "status"),
    "focus",
    []
  )

const setBusy = (context: ControllerContext, busy: boolean): unknown => {
  const value = String(busy)
  const regions: Readonly<ReadonlySet<unknown>> = immutableElements(findTargets(context.element, context.identifier, "region"))
  return Object.freeze({
    element: callMethod(context.element, "setAttribute", ["aria-busy", value]),
    regions: Object.freeze([...regions].map((region) => callMethod(region, "setAttribute", ["aria-busy", value])))
  })
}

const connect = (context: ControllerContext): unknown => {
  const status: unknown = findTarget(context.element, context.identifier, "status")
  return Object.freeze({
    ariaAtomic: callMethod(status, "setAttribute", ["aria-atomic", "true"]),
    ariaLive: callMethod(status, "setAttribute", ["aria-live", "polite"]),
    focused: focusFirstError(context),
    role: callMethod(status, "setAttribute", ["role", "status"])
  })
}

const guard = (context: ControllerContext): unknown =>
  readProperty(context.element, pendingKey) === true ? preventDefault(context.event) : false

const start = (context: ControllerContext): unknown => {
  const controls: Readonly<ReadonlySet<unknown>> = submissionControls(context)
  return readProperty(context.element, pendingKey) === true
    ? false
    : Object.freeze({
        announcement: announce(context, planningMutationStateMessage("saving")),
        busy: setBusy(context, true),
        controls: Object.freeze([...controls].map((control) =>
          readProperty(control, "disabled") === true
            ? false
            : Object.freeze({
                disabled: writeProperty(control, "disabled", true),
                marked: writeProperty(control, disabledKey, true)
              })
        )),
        pending: writeProperty(context.element, pendingKey, true)
      })
}

const finish = (context: ControllerContext): unknown => {
  const controls: Readonly<ReadonlySet<unknown>> = submissionControls(context)
  const success: boolean = readProperty(readProperty(context.event, "detail"), "success") === true
  return Object.freeze({
    announcement: announce(context, planningMutationMessage(success)),
    busy: setBusy(context, false),
    controls: Object.freeze([...controls].map((control) =>
      readProperty(control, disabledKey) === true
        ? Object.freeze({
            disabled: writeProperty(control, "disabled", false),
            marked: writeProperty(control, disabledKey, false)
          })
        : false
    )),
    focused: success ? false : focusFailure(context),
    pending: writeProperty(context.element, pendingKey, false)
  })
}

const PlanningMutationController: FunctionalController = defineController({
  actions: Object.freeze({ dirty: markUnsaved, finish, guard, start }),
  connect
})

export default PlanningMutationController

